function render(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.bsTheme=state.theme;document.documentElement.lang=state.lang;document.title=CONFIG.brand;const description=document.querySelector('meta[name="description"]'),themeColor=document.querySelector('meta[name="theme-color"]');if(description)description.content=({de:'Ein europäischer Marktplatz startet in Deutschland für Architektur und Design, professionelle Services, Flüge, Sport, Kinderprodukte, Landwirtschaft und Shopping.',en:'A European marketplace launching in Germany for architecture, professional services, flight previews, sports, children’s products, agriculture and shopping.',fr:'Un marché européen lancé en Allemagne pour l’architecture, les services professionnels, des aperçus de vols, le sport, les enfants, l’agriculture et le shopping.'})[state.lang]||'A considered European marketplace for independent labels and thoughtful design.';if(themeColor)themeColor.content=state.theme==='dark'?'#171713':'#f3f0e9';document.getElementById('app').innerHTML=header()+ (state.page==='login'?loginPage():state.page==='workspace'?workspace():state.page==='detail'?detailPage():storePage())+footer();bindClearButtons();animateReveals();updateSpin()}
function openMobileMenu(){const menu=document.getElementById('shopMenu');if(!menu)return;if(window.bootstrap?.Offcanvas){bootstrap.Offcanvas.getOrCreateInstance(menu).show();return}if(!document.querySelector('.mobile-nav-backdrop'))menu.insertAdjacentHTML('beforebegin','<div class="mobile-nav-backdrop" data-action="mobile-menu-close" aria-hidden="true"></div>');menu.classList.add('fallback-open');menu.setAttribute('aria-hidden','false');document.body.classList.add('mobile-menu-open')}
function closeMobileMenu(){const menu=document.getElementById('shopMenu');if(!menu)return;if(window.bootstrap?.Offcanvas){bootstrap.Offcanvas.getInstance(menu)?.hide()}menu.classList.remove('fallback-open');menu.setAttribute('aria-hidden','true');document.querySelector('.mobile-nav-backdrop')?.remove();document.body.classList.remove('mobile-menu-open')}
function resetCatalog(){state.category='all';state.query='';state.collection='all';state.visibleCount=PAGE_SIZE;render()}
function catalogList(){let list=P.filter(p=>(state.category==='all'||p.cat===state.category)&&(!state.query||`${p.name} ${p.maker} ${p.cat}`.toLowerCase().includes(state.query.toLowerCase())));const ids=state.collection==='new'?[4,5,6]:state.collection==='edit'?[1,2,5]:null;return ids?list.filter(p=>ids.includes(p.id)):list}
function loadMoreMarkup(total,shown){return `<div class="load-more-wrap" id="load-more-wrap"><small>${t('showingListings').replace('{shown}',shown).replace('{total}',total)}</small>${shown<total?`<button class="button-outline btn btn-outline-secondary" data-action="load-more">${t('loadMore')} <i class="fa-solid fa-arrow-down" aria-hidden="true"></i></button>`:''}</div>`}
function bindClearButtons(){document.querySelectorAll('[data-action="clear"]').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();resetCatalog()})}
function curatedShelf(){if(state.page!=='store'||document.getElementById('curated-shelf'))return;const arrival=document.querySelector('.collection-section .section-heading .overline');if(arrival)arrival.textContent=t('arrival');const spin=document.getElementById('spin-section');if(!spin)return;spin.insertAdjacentHTML('afterend',`<section class="curated-shelf" id="curated-shelf" aria-labelledby="curated-shelf-title"><div class="curated-shelf-heading"><span class="overline">${t('curationNote')}</span><h2 id="curated-shelf-title">${t('categoriesTitle')}</h2></div><div class="curated-shelf-grid"><button class="curated-tile curated-new" type="button" data-collection="new"><img src="${imageUrl(P[5].images[0],800)}" srcset="${imageSrcSet(P[5].images[0])}" sizes="(max-width: 760px) 100vw, 50vw" alt="${esc(P[5].name)}" loading="lazy" decoding="async" onerror="imageFallback(this)"><span><small>01 / ${t('newArrivals')}</small><strong>${t('newArrivals')}</strong><i class="fa-solid fa-arrow-up-right" aria-hidden="true"></i></span></button><button class="curated-tile curated-edit" type="button" data-collection="edit"><img src="${imageUrl(P[4].images[0],800)}" srcset="${imageSrcSet(P[4].images[0])}" sizes="(max-width: 760px) 100vw, 50vw" alt="${esc(P[4].name)}" loading="lazy" decoding="async" onerror="imageFallback(this)"><span><small>02 / ${t('exclusiveFinds')}</small><strong>${t('exclusiveFinds')}</strong><i class="fa-solid fa-arrow-up-right" aria-hidden="true"></i></span></button></div></section>`)}
function applyCollectionFilter(){const ids=state.collection==='new'?[4,5,6]:state.collection==='edit'?[1,2,5]:null;document.querySelectorAll('.product-card[data-product-id]').forEach(card=>{card.hidden=!!ids&&!ids.includes(Number(card.dataset.productId))});const grid=document.querySelector('.editorial-grid'),note=document.getElementById('collection-filter-note');if(ids&&grid&&!note)grid.insertAdjacentHTML('beforebegin',`<p class="collection-filter-note" id="collection-filter-note">${t(state.collection==='new'?'newArrivals':'exclusiveFinds')} · ${t('curationNote')} <button type="button" data-action="clear">${t('clear')}</button></p>`);else if(!ids)note?.remove();else if(note)note.innerHTML=`${t(state.collection==='new'?'newArrivals':'exclusiveFinds')} · ${t('curationNote')} <button type="button" data-action="clear">${t('clear')}</button>`}
function enrichProductDetail(){const detail=document.querySelector('.detail-copy');if(!detail)return;const image=document.getElementById('gallery-image');if(image&&!image.srcset){image.src=imageUrl(image.src,1000);image.srcset=imageSrcSet(image.src);image.sizes='(max-width: 760px) 100vw, 58vw';image.decoding='async'}document.querySelectorAll('.gallery-thumbs img').forEach(thumb=>{if(!thumb.srcset){thumb.src=imageUrl(thumb.src,240);thumb.srcset=imageSrcSet(thumb.src);thumb.sizes='76px';thumb.loading='lazy';thumb.decoding='async'}});if(!detail.querySelector('.product-trust-note'))detail.querySelector('.delivery-detail')?.insertAdjacentHTML('afterend',`<aside class="product-trust-note"><strong><i class="fa-solid fa-box" aria-hidden="true"></i> ${t('returnsTitle')}</strong><p>${t('returnsNote')}</p><small>${t('sellerProvided')}</small></aside>`)}
function enrichWorkspace(){if(state.page!=='workspace'||document.querySelector('.workspace-sample-note'))return;const metrics=document.querySelector('.metrics');if(!metrics)return;metrics.insertAdjacentHTML('afterend',`<p class="workspace-sample-note"><i class="fa-solid fa-circle-info" aria-hidden="true"></i> ${t('metricNote')} · ${t('demoOnly')}</p>`);if(state.role!=='seller')return;const lowStock=state.listings.filter(p=>p.stock<=8);const timeline=state.orders.map(order=>{const phase=['processing','shipped','delivered'].indexOf(order[4]);return `<article class="order-timeline-card"><div><strong>${esc(order[0])}</strong><span>${esc(order[2])}</span></div><ol aria-label="${t('orderTimeline')}">${['processing','shipped','delivered'].map((key,i)=>`<li class="${i<=phase?'is-complete':''}">${t(key)}</li>`).join('')}</ol><small>${t(order[4])} · ${t('demoOnly')}</small></article>`}).join('');metrics.insertAdjacentHTML('afterend',`<section class="seller-operations"><div class="workspace-panel order-timeline"><div class="panel-heading"><div><span class="overline">${t('orderTimeline')}</span><h2>${t('orderManagement')}</h2></div></div><p class="workspace-footnote">${t('timelineNote')}</p>${timeline}</div><div class="workspace-panel inventory-alert"><div class="panel-heading"><div><span class="overline">${t('restockNote')}</span><h2>${t('lowStock')}</h2></div><i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i></div>${lowStock.length?lowStock.map(p=>`<div class="inventory-alert-row"><img src="${imageUrl(p.images[0],480)}" alt="" loading="lazy" decoding="async" onerror="imageFallback(this)"><span><strong>${esc(p.name)}</strong><small>${esc(p.maker)}</small></span><b>${p.stock} ${t('inventoryLabel')}</b></div>`).join(''):`<p class="workspace-footnote">${t('inventoryLabel')}</p>`}</div></section>`)}
function animateReveals(){curatedShelf();applyCollectionFilter();enrichProductDetail();enrichWorkspace();const items=document.querySelectorAll('#app .reveal');if(!('IntersectionObserver' in window)){items.forEach(el=>el.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{rootMargin:'0px 0px -36px 0px'});items.forEach(el=>observer.observe(el))}
let spinRaf=0,currentSpinFrame=-1;const spinFrameCache=new Map();
function requestSpinUpdate(){if(!spinRaf)spinRaf=requestAnimationFrame(updateSpin)}
function updateSpin(){spinRaf=0;const section=document.getElementById('spin-section');if(!section)return;const rect=section.getBoundingClientRect(),travel=Math.max(1,section.offsetHeight-window.innerHeight),progress=Math.min(1,Math.max(0,-rect.top/travel)),stage=document.getElementById('spin-stage');stage.style.setProperty('--spin-progress',progress);const step=Math.min(5,Math.floor(progress*6)),feature=document.getElementById('spin-feature'),number=document.getElementById('spin-story-number'),index=document.getElementById('spin-index');if(stage.dataset.step!==String(step)){stage.dataset.step=String(step);feature.textContent=t(`spinFeature${step+1}`);feature.classList.remove('is-changing');void feature.offsetWidth;feature.classList.add('is-changing');number.textContent=`0${step+1}`;index.textContent=`0${step+1} · 06`}const fill=document.getElementById('spin-meter-fill');if(fill)fill.style.transform=`scaleX(${progress})`;const frames=SPIN_SEQUENCE.frames||[],reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches,note=document.getElementById('spin-asset-note');if(frames.length&&!reduceMotion){currentSpinFrame=Math.min(frames.length-1,Math.round(progress*(frames.length-1)));loadSpinFrame(currentSpinFrame);[-1,1].forEach(d=>{const next=currentSpinFrame+d;if(next>=0&&next<frames.length)preloadSpinFrame(next)});if(note)note.textContent=t('spinReady').replace('{count}',frames.length)}else if(frames.length&&reduceMotion){if(note)note.textContent=t('spinReduced')}else if(note){note.textContent=t('spinFallback')}}
function preloadSpinFrame(index){const src=SPIN_SEQUENCE.frames[index];if(!src||spinFrameCache.has(index))return;const image=new Image();spinFrameCache.set(index,image);image.onload=()=>{image.dataset.ready='true';if(currentSpinFrame===index)showSpinFrame(index)};image.onerror=()=>{spinFrameCache.delete(index);const note=document.getElementById('spin-asset-note');if(note)note.textContent=t('spinFrameError')};image.src=src}
function loadSpinFrame(index){preloadSpinFrame(index);const image=spinFrameCache.get(index);if(image?.dataset.ready==='true')showSpinFrame(index)}
function showSpinFrame(index){const target=document.getElementById('spin-product'),source=SPIN_SEQUENCE.frames[index];if(target&&source&&target.dataset.frame!==String(index)){target.src=source;target.dataset.frame=String(index);target.alt=`${P.find(p=>p.id===SPIN_SEQUENCE.productId)?.name||'Featured product'} · view ${index+1} of ${SPIN_SEQUENCE.frames.length}`;target.classList.remove('frame-updating');void target.offsetWidth;target.classList.add('frame-updating')}}
window.addEventListener('scroll',requestSpinUpdate,{passive:true});window.addEventListener('resize',requestSpinUpdate,{passive:true});
function header(){
  const privateNav=state.page==='workspace';
  return `<header class="masthead navbar navbar-expand-md"><div class="container-fluid px-0"><a class="brand navbar-brand" href="#" data-action="home"><span class="brand-mark">${CONFIG.mark}</span><span>${CONFIG.brand}<small>EUROPEAN MARKETPLACE</small></span></a><nav class="shop-nav navbar-nav" aria-label="${t('discover')}"><button class="nav-link" data-action="category-nav" data-cat="all">${t('discover')}</button><button class="nav-link" data-action="category-nav" data-cat="all">${t('products')}</button><button class="nav-link" data-action="services">${t('services')}</button><button class="nav-link" data-action="collections">${t('filters')}</button><button class="nav-link nav-demo-login" data-action="login"><i class="fa-solid fa-arrow-right-to-bracket" aria-hidden="true"></i> ${t('login')}</button></nav><div class="head-tools"><button class="icon-label search-open" data-action="search" aria-label="${t('search')}"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><small>${t('search')}</small></button><button class="icon-label" data-action="wishlist" aria-label="${t('wishlistLabel')}"><i class="fa-solid fa-heart" aria-hidden="true"></i><small>${t('wishlist')}</small><i class="count-dot">${state.wishlist.length||''}</i></button><button class="icon-label" data-action="account" aria-label="${t('accountHelp')}"><i class="fa-solid fa-user" aria-hidden="true"></i><small>${t('account')}</small></button><button class="icon-label bag-button" data-action="cart" aria-label="${t('cartLabel')}"><i class="fa-solid fa-bag-shopping" aria-hidden="true"></i><small>${t('bag')}</small><i class="count-dot">${state.cart.reduce((a,x)=>a+x.qty,0)||''}</i></button><label class="select-wrap"><span class="sr-only">${t('language')}</span><select class="form-select form-select-sm" id="language-select" aria-label="${t('language')}">${LANGUAGES.map(([code,name])=>`<option value="${code}" ${state.lang===code?'selected':''}>${name}</option>`).join('')}</select></label><span class="market-locale" aria-label="Deutschland, Euro"><i class="fa-solid fa-location-dot" aria-hidden="true"></i><span>DE | EUR</span></span><button class="theme-toggle btn btn-link" data-action="theme" aria-label="${t('themeLabel')}"><i class="fa-solid ${state.theme==='dark'?'fa-sun':'fa-moon'}" aria-hidden="true"></i></button><button class="mobile-toggle btn btn-link" type="button" data-bs-toggle="offcanvas" data-bs-target="#shopMenu" data-action="mobile-menu" aria-controls="shopMenu" aria-label="${t('discover')}"><i class="fa-solid fa-bars" aria-hidden="true"></i></button></div></div></header>${privateNav?`<div class="workspace-ribbon"><span>${t(state.role)} · Demo workspace</span><span><button data-action="logout">${t('logout')}</button><button data-action="home">${t('storefront')}</button></span></div>`:''}<div class="offcanvas offcanvas-end mobile-nav" tabindex="-1" id="shopMenu" aria-labelledby="shopMenuLabel"><div class="offcanvas-header"><h2 class="offcanvas-title" id="shopMenuLabel">${CONFIG.brand}</h2><button type="button" class="btn-close" data-bs-dismiss="offcanvas" data-action="mobile-menu-close" aria-label="${t('close')}"></button></div><div class="offcanvas-body">${['discover','products','filters','services','search','wishlist','cart','account','login',...(privateNav?['logout']:[])].map(k=>`<button class="btn btn-link ${k==='login'?'demo-menu-login':''}" data-bs-dismiss="offcanvas" data-action="${k==='account'?'account':k==='wishlist'?'wishlist':k==='cart'?'cart':k==='search'?'search':k==='services'?'services':k==='filters'?'collections':k==='login'?'login':k==='logout'?'logout':'category-nav'}">${k==='login'?`<i class="fa-solid fa-arrow-right-to-bracket" aria-hidden="true"></i> `:''}${t(k==='cart'?'bag':k)}</button>`).join('')}</div></div>`
}
function footer(){return `<footer class="site-footer"><div><a class="brand" href="#" data-action="home"><span class="brand-mark">${CONFIG.mark}</span><span>${CONFIG.brand}<small>EUROPEAN MARKETPLACE</small></span></a><p>${t('footer')}</p></div><div class="footer-meta"><span>${t('demoOnly')}</span><button data-action="help">${t('help')} ↗</button><button data-action="login">${t('login')}</button></div></footer>`}
function storePage(){const list=catalogList(),visible=list.slice(0,state.visibleCount);return `<main><section class="hero-editorial"><div class="hero-image"><img src="https://images.unsplash.com/photo-1490312278390-ab64016e0aa9?auto=format&fit=crop&w=1900&q=90" alt="Sculptural European homeware in warm afternoon light" fetchpriority="high" decoding="async"><div class="hero-image-label"><span>01 — 07</span><span>EUROPEAN MARKETPLACE · GERMANY</span></div></div><div class="hero-copy"><div class="overline"><span class="line"></span>${t('heroKicker')}</div><h1>${t('heroTitle').replace('\n','<br>')}</h1><p>${t('heroText')}</p><div class="hero-actions"><button class="underlined-link" data-action="shop">${t('explore')} <i class="fa-solid fa-arrow-up-right" aria-hidden="true"></i></button><button class="hero-secondary" data-action="spin-scroll">${t('heroBrowse')} <i class="fa-solid fa-arrow-down" aria-hidden="true"></i></button></div><div class="hero-index"><span>01</span><span class="index-line"></span><span>04</span><small>CURATED IN EUROPE</small></div></div><div class="hero-side-note">THE ART OF<br>FINDING WELL</div></section><nav class="sector-nav" aria-label="${t('heroBrowse')}"><span>${t('heroBrowse')}</span>${CATEGORY_CARDS.map(([key])=>`<button type="button" data-cat="${key}">${t(key)}</button>`).join('')}</nav><section class="spin-section" id="spin-section" aria-label="${t('spinTitle')}"><div class="spin-stage" id="spin-stage"><div class="spin-heading"><span class="overline">${t('spinKicker')}</span><h2>${t('spinTitle')}</h2><p>${t('spinText')}</p><button class="button-dark btn btn-primary" data-action="detail" data-id="1">${t('spinAdd')} <i class="fa-solid fa-arrow-up-right" aria-hidden="true"></i></button></div><div class="spin-visual"><div class="spin-orbit" aria-hidden="true"><span></span></div><img id="spin-product" src="${P[0].images[0]}" alt="${esc(P[0].name)} · ${esc(P[0].description)}" fetchpriority="high"><span class="spin-index" id="spin-index">01 <i>·</i> 06</span><span class="spin-asset-note" id="spin-asset-note" aria-live="off">${t('spinFallback')}</span></div><div class="spin-story"><span class="spin-story-number" id="spin-story-number">01</span><div class="spin-story-copy"><span class="overline">${t('spinScroll')}</span><h3 id="spin-feature">${t('spinFeature1')}</h3></div><div class="spin-meter" aria-hidden="true"><span id="spin-meter-fill"></span></div></div></div></section><section class="benefits"><span><i class="fa-solid fa-leaf" aria-hidden="true"></i> &nbsp;${t('made')}</span><span class="benefit-divider" aria-hidden="true"></span><span><i class="fa-solid fa-truck-fast" aria-hidden="true"></i> &nbsp;${t('delivery')}</span><span class="benefit-divider benefit-divider-last" aria-hidden="true"></span><span><i class="fa-solid fa-circle-info" aria-hidden="true"></i> &nbsp;${t('demoOnly')}</span></section><section class="category-spotlight" id="categories"><div class="category-intro"><span class="overline">${t('categories')}</span><h2>${t('categoriesTitle')}</h2></div><div class="category-tiles">${CATEGORY_CARDS.map(([key,id],i)=>{const p=P.find(item=>item.id===id);return `<button class="category-tile category-tile-${i+1}" data-cat="${key}" aria-label="${t(key)}"><img src="${p.images[0]}" alt="${esc(p.name)}" loading="lazy" onerror="imageFallback(this)"><span class="category-tile-copy"><small>0${i+1} / EUROPEAN MAKERS</small><strong>${t(key)}</strong><i class="fa-solid fa-arrow-up-right" aria-hidden="true"></i></span></button>`}).join('')}</div></section><section class="collection-section" id="collection"><div class="section-heading"><div><div class="overline">${t('arrival')} · 2026</div><h2>${t('curated')}</h2></div><button class="underlined-link" data-action="clear">${t('shopAll')} <span>↗</span></button></div><div class="category-tabs">${[['all','all'],...CATEGORY_CARDS.map(([key])=>[key,key])].map(([key,label])=>`<button class="category-tab ${state.category===key?'selected':''}" data-cat="${key}">${t(label)}</button>`).join('')}<div class="catalog-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input class="form-control form-control-sm" id="catalog-query" type="search" value="${esc(state.query)}" placeholder="${t('searchPlaceholder')}" aria-label="${t('search')}"></div></div>${state.query?`<p class="result-note">${t('searchResults')}: ${list.length}</p>`:''}<div class="editorial-grid row row-cols-2 row-cols-md-3 gy-5">${list.length?visible.map((p,i)=>productCard(p,i)).join(''):`<div class="empty-state"><span><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i></span><h3>${t('noResults')}</h3><p>${t('searchEmpty')}</p><button class="underlined-link" data-action="clear">${t('clear')}</button></div>`}</div>${list.length?loadMoreMarkup(list.length,visible.length):''}</section><section class="brand-story"><div class="story-photo"><img src="https://images.unsplash.com/photo-1494438639946-1ebd1d20bf85?auto=format&fit=crop&w=1300&q=88" loading="lazy" alt="Sunlit European design studio"></div><div class="story-copy"><div class="overline">${t('edit')}</div><h2>${t('story')}</h2><p>${t('storyText')}</p><button class="underlined-link" data-action="shop">${t('explore')} <span>↗</span></button></div></section><section class="service-strip"><div><span class="overline">EUROPEAN MARKETPLACE · GERMANY LAUNCH</span><h2>${t('services')}</h2><p>${t('serviceNote')} ${t('demoOnly')}</p></div><button class="service-card" data-action="services" aria-label="${t('flightPreview')} · ${t('demoOnly')}"><span class="service-symbol"><i class="fa-solid fa-plane" aria-hidden="true"></i></span><strong>${t('flight')}</strong><small>${t('flightPreview')} · ${t('demoOnly')}</small></button><button class="service-card" data-action="services"><span class="service-symbol"><i class="fa-solid fa-handshake" aria-hidden="true"></i></span><strong>${t('services')}</strong><small>${t('servicePreview')} · ${t('demoOnly')}</small></button></section></main>`}
function productCard(p,i){const collectionIds=state.collection==='new'?[4,5,6]:state.collection==='edit'?[1,2,5]:null;return `<article class="product-card reveal col" data-product-id="${p.id}" ${collectionIds&&!collectionIds.includes(p.id)?'hidden':''} style="--reveal-delay:${Math.min(i,5)*70}ms"><div class="product-photo" data-action="quick" data-id="${p.id}"><img src="${imageUrl(p.images[0],800)}" srcset="${imageSrcSet(p.images[0])}" sizes="(max-width: 760px) 50vw, (max-width: 1100px) 33vw, 25vw" alt="${esc(p.name)}" loading="lazy" decoding="async" onerror="imageFallback(this)"><span class="photo-index">0${i+1} / 06</span><span class="product-badge">${t('sellerProvided')} · ${esc(p.badge)}</span><button class="quick-button" type="button" data-action="quick" data-id="${p.id}">${t('quickView')} <span>↗</span></button><button class="wish-button ${state.wishlist.includes(p.id)?'wished':''}" type="button" data-action="wish" data-id="${p.id}" aria-pressed="${state.wishlist.includes(p.id)}" aria-label="${t('wishlistLabel')}: ${esc(p.name)}">${state.wishlist.includes(p.id)?'<i class="fa-solid fa-heart" aria-hidden="true"></i>':'<i class="fa-regular fa-heart" aria-hidden="true"></i>'}</button></div><div class="product-caption"><div><h3>${esc(p.name)}</h3><p>${esc(p.maker)}</p></div><strong>${euro(p.price)}</strong></div><div class="product-subcaption"><span>${t('shippingNote')}</span><button type="button" data-action="detail" data-id="${p.id}">${t('view')} ↗</button></div></article>`}
function loginPage(){const role=state.loginRole||'seller';const account=Object.entries(ACCOUNTS).find(([,a])=>a.role===role);return `<main class="login-shell"><div class="login-art"><img src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=85" alt="Independent design boutique"><div><span class="overline">${t('demoOnly')}</span><h2>${t(role)}</h2></div></div><section class="login-panel"><div class="overline">${t('login')}</div><h1>${t('loginTitle')}</h1><p>${t('loginNote')}</p><div class="portal-switch">${Object.entries(ACCOUNTS).map(([,a])=>`<button class="${role===a.role?'active':''}" data-action="portal" data-role="${a.role}">${t(a.role)}</button>`).join('')}</div><div class="credential-box"><strong>${t('credential')}</strong><span>${account[0]}</span><span>${t('passwordLabel')}: <code>${DEMO_PASSWORD}</code></span></div><form id="login-form"><label>${t('email')}<input class="form-control" name="email" type="email" autocomplete="username" required value="${account[0]}"></label><label>${t('password')}<input class="form-control" name="password" type="password" autocomplete="current-password" required placeholder="${DEMO_PASSWORD}"></label><p class="form-error" id="login-error" role="alert"></p><button class="button-dark btn btn-primary" type="submit">${t('enter')} <span>↗</span></button></form><p class="login-limitation">${t('loginNote')}</p><button class="underlined-link" data-action="home">← ${t('storefront')}</button></section></main>`}
function workspace(){if(!state.role)return loginPage();return `<main class="workspace"><section class="workspace-title"><div><div class="overline">${t(state.role)} · ${t('demoOnly')}</div><h1>${t(state.role+'Title')}</h1><p>${t(state.role+'Desc')}</p></div><button class="button-outline btn btn-outline-secondary" data-action="logout">${t('logout')} ↗</button></section>${state.role==='seller'?sellerWorkspace():state.role==='staff'?staffWorkspace():adminWorkspace()}</main>`}
function metric(label,value,foot){return `<div class="metric col-6 col-lg-3"><span>${t(label)}</span><strong>${value}</strong><small>${foot}</small></div>`}
function sellerWorkspace(){return `<section class="metrics row g-0">${metric('listings',String(state.listings.length).padStart(2,'0'),'↑ 2 this month')}${metric('orders','04','Across your shop')}${metric('sales','€2,486','↑ 12% vs last month')}${metric('inventory','124',t('inventoryLabel'))}</section><div class="workspace-columns"><section class="workspace-panel"><div class="panel-heading"><div><span class="overline">SELLER STUDIO</span><h2>${t('orderManagement')}</h2></div><span class="demo-pill badge">${t('demoOnly')}</span></div><div class="table-scroll table-responsive"><table class="table table-hover align-middle"><thead><tr><th>${t('product')}</th><th>${t('customer')}</th><th>${t('total')}</th><th>${t('status')}</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${esc(o[2])}<small>${o[0]}</small></td><td>${o[1]}</td><td>${euro(o[3])}</td><td><select class="form-select form-select-sm" data-order="${o[0]}" aria-label="${t('status')}">${['processing','shipped','delivered'].map(s=>`<option value="${s}" ${s===o[4]?'selected':''}>${t(s)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></section><section class="workspace-panel listing-panel"><div class="panel-heading"><div><span class="overline">YOUR CATALOGUE</span><h2>${t('listings')}</h2></div><button class="button-small btn btn-sm" data-action="new-listing">＋ ${t('addListing')}</button></div>${state.listings.map(p=>`<div class="listing-row"><img src="${p.images[0]}" alt="" onerror="imageFallback(this)"><div><strong>${esc(p.name)}</strong><small>${p.stock} ${t('inventoryLabel').toLowerCase()}</small></div><b>${euro(p.price)}</b></div>`).join('')}</section></div><div class="workspace-footnote">${t('demoOnly')} · Orders and inventory are sample data; status changes remain in this browser.</div>`}
function staffWorkspace(){return `<section class="metrics row g-0">${metric('enquiries','08','3 need a reply')}${metric('followups','04','2 due today')}${metric('interactions','18','This week · sample data')}${metric('support','96%','Illustrative satisfaction')}</section><div class="workspace-columns"><section class="workspace-panel"><div class="panel-heading"><div><span class="overline">CUSTOMER CARE</span><h2>${t('interactions')}</h2></div><button class="button-small btn btn-sm" data-action="reminder">＋ ${t('reminder')}</button></div>${[['Anna Vogel','Order delivered · botanical candle','Today'],['Felix Braun','Asked about wholesale pricing','Yesterday'],['Mara Hoffmann','Follow-up due · order MP-2039','Today'],['Lea Schneider','Product question · linen tote','Monday']].map((x,i)=>`<div class="interaction-row"><span class="initials">${x[0].split(' ').map(y=>y[0]).join('')}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div><time>${x[2]}</time><button data-action="followup" data-customer="${x[0]}">↗</button></div>`).join('')}</section><section class="workspace-panel"><div class="panel-heading"><div><span class="overline">SUGGESTED COPY</span><h2>${t('templates')}</h2></div></div><div class="suggested"><span class="demo-pill">${t('demoMessage')}</span><p>Hi [Name], thank you for choosing something from our shop. We hope it brings a little joy to your day.</p><button class="text-button" data-action="template">${t('simulate')} ↗</button></div><div class="suggested"><span class="demo-pill">${t('demoMessage')}</span><p>Hi [Name], just checking in to see how everything is going with your recent order. We’re here if you need anything.</p><button class="text-button" data-action="template">${t('simulate')} ↗</button></div><div class="reminder-list"><h3>${t('followups')}</h3>${state.reminders.map(r=>`<p>• &nbsp;${r[0]} · ${r[1]} <small>${r[2]}</small></p>`).join('')}</div></section></div>`}
function adminWorkspace(){return `<section class="metrics row g-0">${metric('volume','€48.2k','↑ 8.4% this month')}${metric('activeSellers','246','16 new this month')}${metric('orders','1,084','Fictional monthly total')}${metric('reviews',String(state.approved),'Awaiting review')}</section><div class="workspace-columns"><section class="workspace-panel"><div class="panel-heading"><div><span class="overline">SELLER ONBOARDING</span><h2>${t('sellerReview')}</h2></div></div>${[['Werkhaus 17','Dresden · Home objects'],['Studio Lune','Lyon · Accessories'],['Nord & Form','Hamburg · Furniture']].map((x,i)=>`<div class="interaction-row"><span class="initials">${x[0][0]}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div><button class="button-small btn btn-sm" data-action="approve" data-name="${x[0]}">${t('approve')}</button></div>`).join('')}<div class="panel-heading subheading"><div><span class="overline">${t('listingReview')}</span><h2>${t('orderManagement')}</h2></div></div><div class="admin-kpis"><p>${t('userMgmt')} <b>1,482</b></p><p>${t('supportQueue')} <b>12</b></p></div></section><section class="workspace-panel"><div class="panel-heading"><div><span class="overline">${t('activity')}</span><h2>${t('platformDemo')}</h2></div></div><div class="admin-activity"><p><i></i><span><b>Form & Field</b> added a new product<small>12 min ago · demo</small></span></p><p><i></i><span><b>Morrow Goods</b> fulfilled an order<small>38 min ago · demo</small></span></p><p><i></i><span><b>Blume Atelier</b> submitted a seller profile<small>2 hours ago · demo</small></span></p></div><div class="settings-box"><h3>${t('platformSettings')}</h3><p>${t('settingText')}</p><label>${t('currencyLabel')} <select><option>EUR (€)</option><option>PLN (planned)</option><option>SEK (planned)</option></select></label><label>${t('country')} <select><option>Germany</option><option>France</option><option>Netherlands</option></select></label></div></section></div>`}
function detailPage(){const p=state.detail||P[0];return `<main class="detail-page"><button class="text-button back-button" data-action="home">← ${t('products')}</button><div class="detail-grid"><div class="gallery"><div class="gallery-main"><img id="gallery-image" src="${p.images[state.slide%p.images.length]}" alt="${esc(p.name)}" onerror="imageFallback(this)"><button class="zoom-hint" data-action="zoom"><i class="fa-solid fa-magnifying-glass-plus" aria-hidden="true"></i> ${t('quickView')}</button><button class="gallery-prev" data-action="slide" data-delta="-1" aria-label="Previous image">←</button><button class="gallery-next" data-action="slide" data-delta="1" aria-label="Next image">→</button></div><div class="gallery-thumbs">${p.images.map((src,i)=>`<button class="${state.slide===i?'active':''}" data-action="slide-to" data-index="${i}" aria-label="Image ${i+1}"><img src="${src}" alt=""></button>`).join('')}</div></div><section class="detail-copy"><div class="overline">${p.badge} · ${p.maker}</div><h1>${esc(p.name)}</h1><div class="detail-price">${euro(p.price)}</div><p>${esc(p.description)}</p><small class="delivery-detail">↗ &nbsp;${t('deliveryInfo')}</small><label class="variant-label">${t('category')}<select><option>${esc(p.color)}</option></select></label><div class="detail-buttons">${p.kind==='service'?`<button class="button-dark btn btn-primary" data-action="service-preview" data-id="${p.id}">${p.cat==='flights'?t('flightPreview'):t('servicePreview')}</button>`:`<button class="button-dark btn btn-primary" data-action="add" data-id="${p.id}">${t('add')} · ${euro(p.price)}</button>`}<button class="button-outline btn btn-outline-secondary" data-action="wish" data-id="${p.id}">${state.wishlist.includes(p.id)?'<i class="fa-solid fa-heart" aria-hidden="true"></i>':'<i class="fa-regular fa-heart" aria-hidden="true"></i>'} &nbsp;${t('wishlist')}</button></div><div class="detail-disclaimer">${p.kind==='service'?t('previewOnly')+'. Illustrative listing and sample price only.':`${t('demoOnly')} · Checkout is not connected. No personal or payment information is requested.`}</div><button class="text-button" data-action="360">360° ${t('quickView')}</button><small class="fallback-note">360° view needs a real multi-angle image set or 3D model; none is provided in this demo.</small></section></div></main>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const el=document.getElementById('toast');el.textContent=message;if(window.bootstrap?.Toast){bootstrap.Toast.getOrCreateInstance(el,{autohide:true,delay:2600}).show();return}el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function openOverlay(html,cls='modal-backdrop'){const root=document.getElementById('overlay-root');if(cls==='drawer-backdrop'){root.innerHTML=`<div class="drawer-backdrop" data-action="backdrop"><section class="drawer" role="dialog" aria-modal="true">${html}</section></div>`;return}root.innerHTML=`<div class="modal fade" id="previewModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-dialog-scrollable"><div class="modal-content preview-modal">${html}</div></div></div>`;if(window.bootstrap?.Modal)bootstrap.Modal.getOrCreateInstance(document.getElementById('previewModal')).show();else document.getElementById('previewModal').classList.add('show')}
function closeOverlay(){const modal=document.getElementById('previewModal');if(modal&&window.bootstrap?.Modal){bootstrap.Modal.getInstance(modal)?.hide();return}document.getElementById('overlay-root').innerHTML=''}
document.addEventListener('hidden.bs.modal',()=>{document.getElementById('overlay-root').innerHTML=''});
function cartDrawer(){openOverlay(`<div class="modal-head"><h2>${t('bag')} · ${state.cart.reduce((a,x)=>a+x.qty,0)}</h2><button data-action="close" aria-label="${t('close')}">×</button></div>${state.cart.length?state.cart.map(x=>{const p=P.find(y=>y.id===x.id);return `<div class="cart-row"><img src="${p.images[0]}" alt=""><div><strong>${p.name}</strong><small>${euro(p.price)}</small><div class="quantity"><button data-action="qty" data-id="${x.id}" data-delta="-1">−</button>${x.qty}<button data-action="qty" data-id="${x.id}" data-delta="1">+</button><button class="text-button" data-action="remove" data-id="${x.id}">${t('remove')}</button></div></div><b>${euro(p.price*x.qty)}</b></div>`}).join(''):`<div class="empty-state"><span><i class="fa-regular fa-heart" aria-hidden="true"></i></span><h3>${t('emptyBag')}</h3><button class="underlined-link" data-action="home">${t('goShop')} ↗</button></div>`}${state.cart.length?`<div class="cart-total"><span>${t('total')}</span><strong>${euro(state.cart.reduce((a,x)=>a+P.find(p=>p.id===x.id).price*x.qty,0))}</strong></div><p class="detail-disclaimer">${t('demoCheckout')}</p><button class="button-dark btn btn-primary full" data-action="checkout">${t('checkout')} ↗</button>`:''}`, 'drawer-backdrop')}
function wishlistPanel(){const items=P.filter(p=>state.wishlist.includes(p.id));openOverlay(`<div class="modal-head"><h2>${t('wishlist')}</h2><button data-action="close">×</button></div>${items.length?items.map(p=>`<div class="cart-row"><img src="${p.images[0]}" alt=""><div><strong>${p.name}</strong><small>${euro(p.price)}</small><button class="text-button" data-action="detail" data-id="${p.id}">${t('view')} ↗</button></div><button data-action="wish" data-id="${p.id}"><i class="fa-solid fa-heart" aria-hidden="true"></i></button></div>`).join(''):`<div class="empty-state"><span><i class="fa-regular fa-heart" aria-hidden="true"></i></span><h3>${t('wishlistEmpty')}</h3></div>`}`, 'drawer-backdrop')}
function quickView(p){openOverlay(`<div class="modal-head"><span class="overline">${t('quickView')}</span><button data-action="close" aria-label="${t('close')}">×</button></div><div class="quick-view"><img src="${imageUrl(p.images[0],900)}" srcset="${imageSrcSet(p.images[0])}" sizes="(max-width: 760px) 90vw, 44vw" alt="${esc(p.name)}" loading="eager" decoding="async" onerror="imageFallback(this)"><div><span class="overline">${t('sellerProvided')} · ${esc(p.badge)}</span><h2>${esc(p.name)}</h2><p>${esc(p.maker)}</p><strong>${euro(p.price)}</strong><p>${esc(p.description)}</p><small class="quick-view-note">${t('returnsNote')}</small><button class="button-dark btn btn-primary full" data-action="detail" data-id="${p.id}">${t('view')} ↗</button></div></div>`, 'modal-backdrop')}
function imageFallback(img){img.onerror=null;img.src='data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 1000"><rect width="800" height="1000" fill="#d9ddd4"/><path d="M0 760 Q200 610 400 760 T800 730 V1000 H0Z" fill="#b8c4b5"/><circle cx="420" cy="400" r="150" fill="#f4f0e8"/><text x="50%" y="92%" text-anchor="middle" font-family="sans-serif" font-size="24" fill="#244b3b">Marketplace Preview</text></svg>`)}
function accessDialog(){openOverlay(`<div class="modal-head"><h2>${t('accountHelp')}</h2><button data-action="close">×</button></div><p>${t('accountText')}</p><p>${t('helpText')}: hello@marketplace-preview.example</p><div class="detail-disclaimer">${t('demoOnly')}</div>`)}
document.addEventListener('change',e=>{if(e.target.id==='language-select'){const lang=e.target.value;if(I18N[lang]){state.lang=lang;savePrefs();render()}else{e.target.value=state.lang;toast('This language is planned; translations are not yet available.')}}if(e.target.matches('[data-order]')){const row=state.orders.find(x=>x[0]===e.target.dataset.order);row[4]=e.target.value;toast(`${row[0]} · ${t(row[4])}`)}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-query'){const pos=e.target.selectionStart;state.query=e.target.value;state.visibleCount=PAGE_SIZE;const grid=document.querySelector('.editorial-grid');const list=catalogList(),visible=list.slice(0,state.visibleCount);grid.innerHTML=list.length?visible.map(productCard).join(''):`<div class="empty-state"><span><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i></span><h3>${t('noResults')}</h3><p>${t('searchEmpty')}</p><button class="underlined-link" data-action="clear">${t('clear')}</button></div>`;bindClearButtons();const loadMore=document.getElementById('load-more-wrap');if(loadMore)loadMore.outerHTML=loadMoreMarkup(list.length,visible.length);let note=document.querySelector('.result-note');if(state.query){const text=`${t('searchResults')}: ${list.length}`;if(note)note.textContent=text;else grid.insertAdjacentHTML('beforebegin',`<p class="result-note">${text}</p>`)}else note?.remove();applyCollectionFilter();animateReveals();e.target.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();const data=new FormData(e.target),email=String(data.get('email')).toLowerCase(),account=ACCOUNTS[email];if(!account||data.get('password')!==DEMO_PASSWORD){document.getElementById('login-error').textContent=t('invalid');return}state.role=account.role;state.page='workspace';history.replaceState({},'',`#${account.role}`);render();window.scrollTo(0,0)}if(e.target.id==='listing-form'){e.preventDefault();const d=new FormData(e.target);const p={id:Date.now(),name:d.get('name'),maker:'Your demo shop · Germany',cat:d.get('category'),price:Number(d.get('price')),stock:12,color:'Natural',images:P[0].images,description:d.get('description')};state.listings.unshift(p);closeOverlay();render();toast(t('saveListing'))}});
document.addEventListener('error',e=>{if(e.target?.tagName==='IMG')imageFallback(e.target)},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-cat]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(b.closest('#shopMenu')&&a!=='mobile-menu-close')closeMobileMenu();if(b.dataset.cat){state.category=b.dataset.cat;state.visibleCount=PAGE_SIZE;render();document.getElementById('collection')?.scrollIntoView({behavior:'smooth'});return}if(a==='mobile-menu'){openMobileMenu()}else if(a==='mobile-menu-close'){closeMobileMenu()}else if(a==='home'){state.page='store';state.role=null;history.replaceState({},'','#');closeOverlay();render();window.scrollTo(0,0)}else if(a==='category-nav'){state.category=b.dataset.cat||'all';state.visibleCount=PAGE_SIZE;state.page='store';render();document.getElementById('collection')?.scrollIntoView({behavior:'smooth'})}else if(a==='shop'||a==='collections'){document.getElementById('collection')?.scrollIntoView({behavior:'smooth'})}else if(a==='spin-scroll'){document.getElementById('spin-section')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}else if(a==='clear'){resetCatalog()}else if(a==='load-more'){const y=window.scrollY;state.visibleCount+=PAGE_SIZE;render();window.scrollTo(0,y)}else if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';savePrefs();render()}else if(a==='search'){document.getElementById('catalog-query')?.focus();document.getElementById('collection')?.scrollIntoView({behavior:'smooth'})}else if(a==='account'){accessDialog()}else if(a==='help'){toast(t('helpText'))}else if(a==='cart'){cartDrawer()}else if(a==='wishlist'){wishlistPanel()}else if(a==='wish'){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];savePrefs();if(state.page==='store')render();else if(document.querySelector('.drawer-backdrop'))wishlistPanel();else render();toast(t(state.wishlist.includes(id)?'wishlistAdded':'wishlistRemoved'))}else if(a==='quick'){const p=P.find(x=>x.id===id);if(p)quickView(p)}else if(a==='detail'){state.detail=P.find(x=>x.id===id)||state.detail;state.slide=0;state.page='detail';closeOverlay();render();window.scrollTo(0,0)}else if(a==='add'){const found=state.cart.find(x=>x.id===id);found?found.qty++:state.cart.push({id,qty:1});savePrefs();render();toast(t('addedToast'))}else if(a==='qty'){const item=state.cart.find(x=>x.id===id);item.qty+=Number(b.dataset.delta);if(item.qty<1)state.cart=state.cart.filter(x=>x.id!==id);savePrefs();cartDrawer()}else if(a==='remove'){state.cart=state.cart.filter(x=>x.id!==id);savePrefs();cartDrawer()}else if(a==='service-preview'){toast('Preview only · no booking or provider contact is available.') }else if(a==='checkout'){closeOverlay();toast(t('demoCheckout'))}else if(a==='close'){closeOverlay()}else if(a==='backdrop'&&e.target===b){document.getElementById('overlay-root').innerHTML=''}else if(a==='login'){state.loginRole='seller';state.page='login';render();window.scrollTo(0,0)}else if(a==='portal'){state.loginRole=b.dataset.role;render()}else if(a==='logout'){state.role=null;state.page='store';history.replaceState({},'','#');render();window.scrollTo(0,0);toast(t('logout'))}else if(a==='services'){openOverlay(`<div class="modal-head"><h2>${t('services')}</h2><button data-action="close">×</button></div><p>${t('serviceNote')}</p><div class="detail-disclaimer">${t('flight')} · no live providers, booking or ticketing are connected.</div>`)}else if(a==='new-listing'){openOverlay(`<div class="modal-head"><h2>${t('addListing')}</h2><button data-action="close">×</button></div><p>${t('demoOnly')}</p><form id="listing-form"><label>${t('listingName')}<input class="form-control" name="name" required></label><div class="form-two"><label>${t('price')}<input class="form-control" name="price" type="number" min="1" required></label><label>${t('category')}<select class="form-select" name="category">${CATEGORY_CARDS.map(([key])=>`<option value="${key}">${t(key)}</option>`).join('')}</select></label></div><label>${t('description')}<textarea class="form-control" name="description"></textarea></label><button class="button-dark btn btn-primary full">${t('saveListing')}</button></form>`)}else if(a==='followup'||a==='template'){openOverlay(`<div class="modal-head"><h2>${t('simulate')}</h2><button data-action="close">×</button></div><p>${t('demoMessage')}</p><label>${t('customer')}<input value="${esc(b.dataset.customer||'Mara Hoffmann')}" readonly></label><label>${t('templates')}<textarea class="form-control">Hi [Name], thank you for choosing something from our shop. We hope it brings a little joy to your day.</textarea></label><div class="detail-disclaimer">${t('notSent')}</div><button class="button-dark btn btn-primary full" data-action="confirm-followup">${t('followupAction')}</button>`)}else if(a==='confirm-followup'){state.reminders.unshift(['Mara Hoffmann','Demo follow-up scheduled','Today · just now']);closeOverlay();render();toast(t('notSent'))}else if(a==='reminder'){openOverlay(`<div class="modal-head"><h2>${t('reminder')}</h2><button data-action="close">×</button></div><label>${t('customer')}<select class="form-select"><option>Mara Hoffmann</option><option>Anna Vogel</option><option>Felix Braun</option></select></label><label>${t('reminder')}<input class="form-control" type="date" value="2026-10-20"></label><button class="button-dark btn btn-primary full" data-action="save-reminder">${t('save')}</button>`)}else if(a==='save-reminder'){state.reminders.unshift(['Mara Hoffmann','New sample reminder','Tomorrow · 10:00']);closeOverlay();render();toast(t('save'))}else if(a==='approve'){state.approved=Math.max(0,state.approved-1);b.closest('.interaction-row').remove();toast(`${b.dataset.name} · ${t('approve')}`)}else if(a==='slide'){state.slide=(state.slide+Number(b.dataset.delta)+state.detail.images.length)%state.detail.images.length;render()}else if(a==='slide-to'){state.slide=Number(b.dataset.index);render()}else if(a==='zoom'){const img=document.getElementById('gallery-image');img.classList.toggle('zoomed')}else if(a==='360'){toast('360° view unavailable: real angle images or 3D model required.')}});
document.addEventListener('click',e=>{if(e.target.closest('[data-cat]'))state.collection='all'},true);
document.addEventListener('click',e=>{const button=e.target.closest('[data-collection]');if(!button)return;state.collection=button.dataset.collection;state.category='all';state.query='';state.visibleCount=PAGE_SIZE;render();document.getElementById('collection')?.scrollIntoView({behavior:'smooth'})});
document.addEventListener('change',e=>{if(e.target.matches('[data-order]')&&state.page==='workspace'){const y=window.scrollY;render();window.scrollTo(0,y)}});
render();
